 projects:[['name','اسم المشروع','Project name'],['description','وصف المشروع','Description','textarea'],['technologies','التقنيات أو المهارات المستخدمة','Technologies'],['url','رابط المشروع','Project URL','url'],['date','تاريخ المشروع','Project date','month']],
 achievements:[['title','عنوان الإنجاز','Achievement title'],['description','وصف الإنجاز','Description','textarea'],['date','التاريخ','Date','month']],
 volunteering:[['organization','اسم الجهة','Organization'],['role','الدور التطوعي','Volunteer role'],['start_date','تاريخ البداية','Start date','month'],['end_date','تاريخ النهاية','End date','month'],['description','وصف المهام','Description','textarea']],
 references:[['name','الاسم','Name'],['job_title','المسمى الوظيفي','Job title'],['company','جهة العمل','Company'],['phone','رقم التواصل','Phone'],['email','البريد الإلكتروني','Email','email']]
};
const steps=['personal',...state.section_order,'controls']; let current=0,saveTimer=null,drag={x:0,y:0,scale:1},rawPhoto=null;
const ar=()=>state.language==='ar',t=(key)=>labels[state.language][key]||key,esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function init(){state.content.personal ||= {}; for(const k of Object.keys(configs)){if(k==='references'){state.content[k]||={available_on_request:false,items:[]};state.content[k].items||=[]}else state.content[k]||=[]} renderSteps();renderPages();renderPreview(); if(photoUrl){previewPhoto.src=photoUrl;previewPhotoPlaceholder.style.display='none'} secureScreen(!paid); document.addEventListener('contextmenu',e=>{if(!paid)e.preventDefault()});document.addEventListener('dragstart',e=>{if(!paid)e.preventDefault()});document.addEventListener('keydown',e=>{if(!paid&&(((e.ctrlKey||e.metaKey)&&['s','p','u','c'].includes(e.key.toLowerCase()))||e.key==='PrintScreen')){e.preventDefault();hideForCapture()}});document.addEventListener('visibilitychange',()=>document.body.classList.toggle('capture-hidden',!paid&&document.hidden));window.addEventListener('blur',hideForCapture);window.addEventListener('focus',()=>setTimeout(()=>document.body.classList.remove('capture-hidden'),250))}
function secureScreen(on){try{ResumeSecurity.postMessage(on?'secure':'open')}catch(e){}}
function hideForCapture(){if(!paid)document.body.classList.add('capture-hidden')}
function renderSteps(){steps.splice(0,steps.length,'personal',...state.section_order,'controls');document.getElementById('steps').innerHTML=steps.map((s,i)=>`<button class="step ${i===current?'active':''}" onclick="go(${i})">${i+1}. ${t(s)}</button>`).join('')}
function personalPage(){const p=state.content.personal;const fields=[['full_name','الاسم الكامل','Full name','text',1],['job_title','المسمى الوظيفي أو التخصص','Job title or major','text',1],['summary','نبذة تعريفية مختصرة','Professional summary','textarea'],['phone','رقم الجوال','Phone'],['email','البريد الإلكتروني','Email','email'],['city','المدينة','City'],['country','الدولة','Country'],['birth_date','تاريخ الميلاد (اختياري)','Birth date','date'],['nationality','الجنسية (اختياري)','Nationality'],['marital_status','الحالة الاجتماعية (اختياري)','Marital status'],['linkedin','رابط LinkedIn (اختياري)','LinkedIn URL','url'],['website','الموقع أو معرض الأعمال (اختياري)','Website or portfolio','url']];return `<div class="step-page active"><h2>${t('personal')}</h2><div class="grid">${fields.map(f=>fieldHtml('personal',0,f,p[f[0]]??'')).join('')}<div class="field full"><label>الصورة الشخصية (اختياري)</label><input type="file" accept="image/*" onchange="loadPhoto(event)"><div class="photo-editor" id="photoEditor"><div class="crop-stage" id="cropStage"><img id="cropImage"></div><label>تكبير وتصغير</label><input class="range" type="range" min="1" max="3" step=".05" value="1" oninput="zoomPhoto(this.value)"><div class="footer-actions"><button class="secondary" type="button" onclick="deletePhoto()">حذف الصورة</button><button class="primary" type="button" onclick="savePhoto()">حفظ القص</button></div></div></div></div></div>`}
function fieldHtml(section,index,f,value){const [key,arLabel,enLabel,type='text',required=0]=f,label=ar()?arLabel:enLabel,id=`${section}-${index}-${key}`,change=`setValue('${section}',${index},'${key}',this.${type==='checkbox'?'checked':'value'})`;let input;if(type==='textarea')input=`<textarea id="${id}" oninput="${change}">${esc(value)}</textarea>`;else if(type==='checkbox')input=`<input id="${id}" type="checkbox" ${value?'checked':''} onchange="${change}">`;else if(type==='skill_level'||type==='language_level'){const opts=type==='skill_level'?['','مبتدئ','متوسط','جيد','جيد جداً','متقدم','محترف']:['','مبتدئ','متوسط','جيد','جيد جداً','متقدم','اللغة الأم'];input=`<select id="${id}" onchange="${change}">${opts.map(o=>`<option ${o===value?'selected':''}>${o}</option>`).join('')}</select>`}else input=`<input id="${id}" type="${type}" value="${esc(value)}" ${required?'required':''} oninput="${change}">`;return `<div class="field ${type==='textarea'?'full':''}"><label for="${id}">${label}${required?' <span class=required>*</span>':''}</label>${input}</div>`}
function itemsPage(section){const ref=section==='references',items=ref?state.content.references.items:state.content[section];return `<div class="step-page active"><h2>${t(section)}</h2>${ref?`<label class="field"><span>المراجع متاحة عند الطلب</span><input type="checkbox" ${state.content.references.available_on_request?'checked':''} onchange="state.content.references.available_on_request=this.checked;changed()"></label>`:''}<div class="items">${items.map((item,i)=>`<div class="item-card"><div class="item-head"><strong>${t(section)} ${i+1}</strong><div class="item-actions"><button class="small" onclick="moveItem('${section}',${i},-1)">↑</button><button class="small" onclick="moveItem('${section}',${i},1)">↓</button><button class="small danger" onclick="removeItem('${section}',${i})">حذف</button></div></div><div class="grid">${configs[section].map(f=>fieldHtml(section,i,f,item[f[0]]??'')).join('')}</div></div>`).join('')}</div><button class="add" onclick="addItem('${section}')">+ إضافة ${t(section)}</button></div>`}
function controlsPage(){return `<div class="step-page active"><h2>${t('controls')}</h2><div class="grid"><div class="field full"><label>لغة السيرة الذاتية</label><select onchange="state.language=this.value;document.documentElement.lang=state.language;document.documentElement.dir=ar()?'rtl':'ltr';changed();renderAll()"><option value="ar" ${ar()?'selected':''}>العربية</option><option value="en" ${!ar()?'selected':''}>English</option></select></div><div class="field full"><label>اختر التصميم الفاخر</label><div class="template-grid">${Object.entries(templates).map(([id,name])=>`<button type="button" class="template-card ${state.template_id===id?'active':''}" data-template="${id}" onclick="chooseTemplate('${id}')"><span class="template-mini"></span><strong>${name}</strong></button>`).join('')}</div></div></div><h3>إظهار وترتيب الأقسام</h3><div class="section-controls">${state.section_order.map((s,i)=>`<div class="section-control"><strong>${t(s)}</strong><label><input type="checkbox" ${state.hidden_sections.includes(s)?'':'checked'} onchange="toggleSection('${s}',this.checked)"> إظهار</label><button class="small" onclick="moveSection(${i},-1)">↑</button><button class="small" onclick="moveSection(${i},1)">↓</button></div>`).join('')}</div></div>`}
function renderPages(){const s=steps[current];pages.innerHTML=s==='personal'?personalPage():s==='controls'?controlsPage():itemsPage(s);prevButton.style.visibility=current?'visible':'hidden';nextButton.style.display=current<steps.length-1?'block':'none';checkoutButton.style.display=current===steps.length-1&&!paid?'block':'none';attachCropDrag()}
function renderAll(){renderSteps();renderPages();renderPreview()}
function chooseTemplate(id){state.template_id=id;changed();renderAll()}
function go(i){current=Math.max(0,Math.min(i,steps.length-1));renderAll()} prevButton.onclick=()=>go(current-1);nextButton.onclick=()=>go(current+1);
function getItems(s){return s==='references'?state.content.references.items:state.content[s]}
function setValue(s,i,k,v){if(s==='personal')state.content.personal[k]=v;else getItems(s)[i][k]=v;changed()}
function addItem(s){getItems(s).push({});changed();renderAll()}function removeItem(s,i){getItems(s).splice(i,1);changed();renderAll()}function moveItem(s,i,d){const a=getItems(s),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];changed();renderAll()}function moveSection(i,d){const j=i+d;if(j<0||j>=state.section_order.length)return;[state.section_order[i],state.section_order[j]]=[state.section_order[j],state.section_order[i]];changed();renderAll()}function toggleSection(s,shown){state.hidden_sections=shown?state.hidden_sections.filter(x=>x!==s):[...new Set([...state.hidden_sections,s])];changed();renderPreview()}
function changed(){renderPreview();saveState.textContent='جارٍ الحفظ...';clearTimeout(saveTimer);saveTimer=setTimeout(save,650)}
async function save(){if(paid)return true;try{const r=await fetch(@json(route('resume.update',$draft)),{method:'PATCH',headers:{'X-CSRF-TOKEN':csrf,'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(state)});const j=await r.json();if(!r.ok)throw j;saveState.textContent='تم الحفظ تلقائيًا';return true}catch(e){saveState.textContent='تعذر الحفظ — تحقق من البيانات';errorBox.textContent=e?.message||Object.values(e?.errors||{}).flat()[0]||'تحقق من البيانات المطلوبة ثم حاول مرة أخرى.';errorBox.classList.add('show');return false}}
function sectionHtml(s){const items=getItems(s);if(s==='references'&&state.content.references.available_on_request)return `<section class="cv-section cv-section-${s}"><h3>${t(s)}</h3><div class=cv-body>${ar()?'المراجع متاحة عند الطلب':'References available upon request'}</div></section>`;if(!items?.length)return'';return `<section class="cv-section cv-section-${s}"><h3><span class=cv-section-mark></span>${t(s)}</h3><div class=cv-section-items>${items.map(item=>{const title=item.qualification||item.job_title||item.name||item.title||item.role||item.organization||'';const sub=item.institution||item.company||item.issuer||item.organization||'';const date=[item.start_date,item.end_date||item.date||((item.current)&&(ar()?'حتى الآن':'Present'))].filter(Boolean).join(' — ');const meta=[item.major,item.location,item.grade,item.technologies].filter(Boolean);const desc=item.description||item.achievements||'';return `<article class=cv-item><div class=cv-item-heading><strong>${esc(title)}</strong>${date?`<time>${esc(date)}</time>`:''}${item.level?`<span class=cv-level>${esc(item.level)}</span>`:''}</div>${sub&&sub!==title?`<small class=cv-organization>${esc(sub)}</small>`:''}${meta.length?`<div class=cv-item-meta>${meta.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}${desc?`<div class=cv-body>${esc(desc)}</div>`:''}${item.url?`<div class=cv-link>${esc(item.url)}</div>`:''}</article>`}).join('')}</div></section>`}
function personalHtml(p){const address=[p.city,p.country].filter(Boolean).join(ar()?'، ':', '),rows=[[`☎`,ar()?'رقم الجوال':'Phone',p.phone],[`✉`,ar()?'البريد الإلكتروني':'Email',p.email],[`⌂`,ar()?'العنوان':'Address',address],[`◫`,ar()?'تاريخ الميلاد':'Birth date',p.birth_date],[`◆`,ar()?'الجنسية':'Nationality',p.nationality],[`●`,ar()?'الحالة الاجتماعية':'Marital status',p.marital_status],[`in`,'LinkedIn',p.linkedin],[`↗`,ar()?'الموقع الشخصي':'Website',p.website]].filter(x=>x[2]);if(!rows.length)return'';return `<section class="cv-section cv-personal-section"><h3>${ar()?'المعلومات الشخصية':'Personal Information'}</h3><div class=cv-personal-list>${rows.map(x=>`<div class=cv-personal-row><span class=cv-personal-icon>${x[0]}</span><div><strong>${x[1]}</strong><span>${esc(x[2])}</span></div></div>`).join('')}</div></section>`}
function previewDensity(){const count=state.section_order.filter(s=>!state.hidden_sections.includes(s)).reduce((n,s)=>n+(getItems(s)?.length||0),0),length=JSON.stringify(state.content).length;return count<=5&&length<1500?'sparse':(count>=15||length>5000?'dense':'balanced')}
function renderPreview(){const p=state.content.personal||{};previewName.textContent=p.full_name||(ar()?'الاسم الكامل':'Full name');previewJob.textContent=p.job_title||(ar()?'المسمى الوظيفي':'Job title');previewPhotoPlaceholder.textContent=(p.full_name||'CV').trim().charAt(0)||'CV';sideContent.innerHTML=personalHtml(p)+state.section_order.filter(s=>!state.hidden_sections.includes(s)&&['skills','languages','references'].includes(s)).map(sectionHtml).join('');mainContent.innerHTML=(p.summary?`<section class="cv-section cv-summary"><h3><span class=cv-section-mark></span>${ar()?'الملف المهني':'Professional Profile'}</h3><div class=cv-body>${esc(p.summary)}</div></section>`:'')+state.section_order.filter(s=>!state.hidden_sections.includes(s)&&!['skills','languages','references'].includes(s)).map(sectionHtml).join('');resumePage.dir=ar()?'rtl':'ltr';resumePage.className=`cv-sheet template-${state.template_id} content-${previewDensity()}`}
function loadPhoto(e){const f=e.target.files[0];if(!f)return;rawPhoto=f;const u=URL.createObjectURL(f);cropImage.src=u;photoEditor.classList.add('active');drag={x:0,y:0,scale:1};cropImage.onload=()=>positionPhoto()}
function attachCropDrag(){const stage=document.getElementById('cropStage');if(!stage)return;let active=false,sx=0,sy=0;stage.onpointerdown=e=>{active=true;sx=e.clientX-drag.x;sy=e.clientY-drag.y;stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(!active)return;drag.x=e.clientX-sx;drag.y=e.clientY-sy;positionPhoto()};stage.onpointerup=()=>active=false}
function zoomPhoto(v){drag.scale=Number(v);positionPhoto()}function positionPhoto(){if(!cropImage.naturalWidth)return;const base=Math.max(260/cropImage.naturalWidth,260/cropImage.naturalHeight),w=cropImage.naturalWidth*base*drag.scale,h=cropImage.naturalHeight*base*drag.scale;cropImage.style.width=w+'px';cropImage.style.height=h+'px';cropImage.style.left=((260-w)/2+drag.x)+'px';cropImage.style.top=((260-h)/2+drag.y)+'px'}
async function savePhoto(){const c=document.createElement('canvas');c.width=c.height=800;const ctx=c.getContext('2d'),img=cropImage,scale=800/260;ctx.drawImage(img,parseFloat(img.style.left)*scale,parseFloat(img.style.top)*scale,parseFloat(img.style.width)*scale,parseFloat(img.style.height)*scale);c.toBlob(async b=>{const fd=new FormData();fd.append('photo',b,'photo.png');const r=await fetch(@json(route('resume.photo',$draft)),{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:fd});const j=await r.json();if(r.ok){previewPhoto.src=j.photo_url+'?v='+Date.now();previewPhotoPlaceholder.style.display='none';photoEditor.classList.remove('active')}} ,'image/png',.95)}
async function deletePhoto(){await fetch(@json(route('resume.photo.destroy',$draft)),{method:'DELETE',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'}});previewPhoto.removeAttribute('src');previewPhotoPlaceholder.style.display='grid';photoEditor?.classList.remove('active')}
let addingToCart=false;checkoutForm.addEventListener('submit',async e=>{if(addingToCart)return;e.preventDefault();checkoutButton.disabled=true;checkoutButton.textContent='جارٍ الإضافة إلى السلة...';if(await save()){addingToCart=true;checkoutForm.submit();return}checkoutButton.disabled=false;checkoutButton.textContent='إضافة إلى السلة — 5 ريالات'});
window.addEventListener('beforeunload',()=>secureScreen(false));init();
</script>
</body>
</html>
